import requests
from urllib.parse import quote
q='("alcoholic hepatitis" OR "alcoholic liver disease") AND (laminin) AND ("type IV collagen" OR collagen IV)'
u='https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esearch.fcgi?db=pubmed&term='+quote(q)+'&retmax=20&retmode=json'
r=requests.get(u,timeout=20); print('status',r.status_code); ids=r.json()['esearchresult']['idlist']; print('ids',ids)
if ids:
 x=requests.get('https://eutils.ncbi.nlm.nih.gov/entrez/eutils/esummary.fcgi',params={'db':'pubmed','id':','.join(ids),'retmode':'json'},timeout=20).json()['result']
 for i in ids: print(i,x[i].get('pubdate'),x[i].get('title'),x[i].get('fulljournalname'))
else: print('No PubMed matches')
print('query',q)
